export function resolvePlannedOpName(raw: string): string {
  const lower = String(raw || '').trim().toLowerCase();
  return PLANNED_OP_NAMES.get(lower) ?? lower;
}

// The op list shown to the manager model. Built from the same table the
// C++ validator uses, so the prompt can never offer an op that is rejected.
export function buildPlannedOpsPromptBlock(): string {
  return PLANNED_OPS
      .map((op) => {
        const target = op.targets.length ?
            op.targets.map((t) => (t === 'primary' ? 'target' : t)).join(' + ') :
            'no target';
        const args = op.args.length ? `; args: ${op.args.join(', ')}` : '';
        return `${op.name} (${target}${args}) - ${op.summary}`;
      })
      .join('\n');
}
